/** Additive, offline catalogue records for the content expansion. IDs are stable so seeding is repeatable. */
internal fun expandedOpportunities(): List<OpportunityEntity> =
    universities() + careers() + scholarships() + internships() + training()

private data class UniversitySeed(
    val name: String, val country: String, val city: String, val campus: String, val url: String,
    val note: String = ""
)

