        UniversitySeed("Yale University", "United States", "New Haven, Connecticut", "New Haven campus", "https://www.yale.edu/"),
        UniversitySeed("University of Oxford", "United Kingdom", "Oxford, England", "Oxford colleges and departments", "https://www.ox.ac.uk/"),
        UniversitySeed("University of Cambridge", "United Kingdom", "Cambridge, England", "Cambridge colleges and departments", "https://www.cam.ac.uk/"),
        UniversitySeed("Imperial College London", "United Kingdom", "London, England", "South Kensington campus", "https://www.imperial.ac.uk/"),
        UniversitySeed("University of Manchester", "United Kingdom", "Manchester, England", "Manchester campus", "https://www.manchester.ac.uk/"),
        UniversitySeed("University of Edinburgh", "United Kingdom", "Edinburgh, Scotland", "Edinburgh campuses", "https://www.ed.ac.uk/"),
        UniversitySeed("Indian Institute of Technology Bombay", "India", "Mumbai, Maharashtra", "Powai campus", "https://www.iitb.ac.in/"),
        UniversitySeed("Indian Institute of Technology Delhi", "India", "New Delhi", "Hauz Khas campus", "https://home.iitd.ac.in/"),
        UniversitySeed("University of Delhi", "India", "New Delhi", "North and South Campuses", "https://www.du.ac.in/"),
        UniversitySeed("Jawaharlal Nehru University", "India", "New Delhi", "New Delhi campus", "https://www.jnu.ac.in/"),
        UniversitySeed("University of Mumbai", "India", "Mumbai, Maharashtra", "Fort campus and affiliated colleges", "https://mu.ac.in/"),
        UniversitySeed("University of Barcelona", "Spain", "Barcelona, Catalonia", "Barcelona campuses", "https://www.ub.edu/"),
        UniversitySeed("Autonomous University of Madrid", "Spain", "Madrid", "Cantoblanco campus", "https://www.uam.es/"),
        UniversitySeed("Complutense University of Madrid", "Spain", "Madrid", "Moncloa campus", "https://www.ucm.es/"),
        UniversitySeed("University of Valencia", "Spain", "Valencia", "Valencia campuses", "https://www.uv.es/"),
        UniversitySeed("University of Granada", "Spain", "Granada, Andalusia", "Granada campuses", "https://www.ugr.es/"),
        UniversitySeed("University of Malawi", "Malawi", "Zomba", "Zomba campus", "https://unima.ac.mw/"),
        UniversitySeed("Kamuzu University of Health Sciences (KUHeS)", "Malawi", "Blantyre and Lilongwe", "Blantyre and Lilongwe campuses", "https://kuhes.ac.mw/", "Current institution name. The supplied 'Kamuzu College of Health Sciences' label is not listed as a separate current university; KUHeS was formed from the former College of Medicine and Kamuzu College of Nursing."),
        UniversitySeed("Malawi University of Science and Technology (MUST)", "Malawi", "Thyolo", "Thyolo campus", "https://must.ac.mw/"),
        UniversitySeed("Mzuzu University", "Malawi", "Mzuzu", "Luwinga campus", "https://www.mzuni.ac.mw/"),
        UniversitySeed("Lilongwe University of Agriculture and Natural Resources (LUANAR)", "Malawi", "Lilongwe", "Bunda and NRC campuses", "https://www.luanar.ac.mw/"),
        UniversitySeed("Catholic University of Malawi", "Malawi", "Nguludi, Blantyre District", "Montfort campus", "https://cu.cunima.digital/"),
        UniversitySeed("University of Livingstonia", "Malawi", "Laws, Livingstonia", "Laws campus and other sites", "https://unilia.ac.mw/"),
        UniversitySeed("Malawi Adventist University", "Malawi", "Ntcheu", "Malawi Adventist campus", "https://mau.ac.mw/"),
        UniversitySeed("Daeyang University", "Malawi", "Lilongwe (campus details not confirmed)", "Campus location not confirmed in an official source", ""),
        UniversitySeed("Exploits University", "Malawi", "Lilongwe", "Lilongwe campus", "https://exploitsmw.com/")
    )
    return items.map { u ->
        val id = if (u.name == "University of Malawi") "uni-malawi" else
            "uni-expanded-" + u.name.lowercase().replace(Regex("[^a-z0-9]+"), "-").trim('-')
        OpportunityEntity(
            id = id, title = u.name, category = "Universities",
            subtitle = "${u.country} · ${u.city}",
            overview = "${u.name} is located in ${u.city}, ${u.country}. Campus information: ${u.campus}. Programme availability, award titles, lengths, entry rules, fees, and application procedures vary by course and intake; confirm each item in the official catalogue before applying.",
            qualifications = "",
            courses = "",
            skills = "",
            pathways = "Application procedure: use the official university website to find the current programme and admissions instructions. Prepare qualifications and supporting documents listed for the selected intake. Application opening/closing dates and fees: ${"not confirmed; check the official admissions notice"}.",
            provider = "Official website: ${u.url.ifBlank { "not confirmed; check Malawi NCHE institution listings" }}\nSource checked: $verification" + if (u.note.isNotBlank()) "\nInstitution note: ${u.note}" else "",
            requirements = "General admission requirements are programme- and applicant-specific. Information not confirmed — check the official provider. No programme duration or entry grade is assumed.",
            duration = "Programme-specific; not confirmed in this listing.",
            deadline = "Application dates have not yet been announced or verified for a specific intake. Check the official university admissions website.",
            applicationUrl = u.url
        )
    }
}

private data class CareerSeed(val title: String, val group: String, val description: String, val duties: String, val subjects: String, val qualifications: String, val skills: String, val progression: String, val sectors: String, val training: String)

private fun careers(): List<OpportunityEntity> {
    val tech = "Technology"
    val health = "Health Science"
    val design = "Design"
    val rows = listOf(
        CareerSeed("Software Developer", tech, "Creates and maintains applications, services, and software tools that solve user or organisational problems.", "Clarify requirements; design solutions; write and review code; test software; fix defects; document and maintain releases.", "Mathematics, computer studies, and physics are useful preparation where available; verify local university prerequisites.", "Common routes include BSc Computer Science, BSc Software Engineering, or BSc Information Technology. Specific awards, providers, and durations must be checked in official prospectuses.", "Programming, algorithms, debugging, testing, databases, version control, teamwork, and clear communication.", "Junior developer to developer, senior developer, technical lead, software architect, or engineering manager.", "Software firms, banks, government, telecommunications, education, health, and in-house technology teams.", "Build a portfolio and practical projects; optional vendor or language certificates are not substitutes for a degree."),
        CareerSeed("Cybersecurity Analyst", tech, "Monitors systems and investigates weaknesses or security events to reduce harm to an organisation's networks and information.", "Review alerts; assess vulnerabilities; help investigate incidents; document findings; recommend controls; support security awareness.", "Mathematics, computer studies, physics, and English support technical and reporting work.", "Common routes include BSc Computer Science, Information Technology, Computer Networks, or a related computing degree. Dedicated cybersecurity awards and durations depend on provider.", "Networking, operating systems, scripting, security principles, risk assessment, careful documentation, and teamwork.", "IT support or network technician to security analyst to incident responder, security engineer, architect, or security manager.", "Banks, telecoms, public services, consultancies, technology companies, and organisations with security operations.", "Practical labs and vendor-neutral or vendor certifications may support experience; confirm certification prerequisites with the issuer."),
        CareerSeed("Data Scientist", tech, "Uses programming, statistics, and subject knowledge to find patterns in data and communicate evidence that can guide decisions.", "Collect and clean data; select analytical methods; build and evaluate models; visualise results; explain limits and findings.", "Mathematics, additional mathematics, statistics, computer studies, and sciences are useful preparation.", "Common routes include BSc Data Science where offered, Statistics, Mathematics, Computer Science, or related quantitative degrees. Check actual course titles and durations.", "Statistics, programming, data management, visualisation, critical thinking, model evaluation, and communication.", "Data analyst or research assistant to data scientist to specialist, analytics lead, or applied researcher.", "Research, finance, health, agriculture, government, retail, telecommunications, and technology.", "Develop a portfolio with responsible data projects; postgraduate study may be preferred for some research roles."),
        CareerSeed("Network Engineer", tech, "Plans, installs, and supports the wired, wireless, and cloud networks that connect users, devices, and services.", "Configure network equipment; monitor availability; troubleshoot faults; manage access; document changes; support resilience and security.", "Mathematics, computer studies, physics, and technical subjects are useful.", "Common routes include BSc Computer Networks, Information Technology, Computer Science, or electrical/electronic engineering; verify programme names with institutions.", "Routing, switching, wireless, network security, troubleshooting, cloud basics, documentation, and customer communication.", "Support technician to network administrator or engineer to network architect or infrastructure lead.", "Telecommunications, internet providers, government, banks, campuses, hospitals, and managed service providers.", "Hands-on labs and current networking certifications may help; issuer requirements and fees vary."),
        CareerSeed("Artificial Intelligence Engineer", tech, "Builds software that applies machine learning or other AI methods to tasks such as prediction, language, vision, or automation.", "Prepare data; select and train models; evaluate safety and performance; integrate models into products; monitor and improve deployments.", "Mathematics, statistics, computer studies, physics, and English are useful.", "Common routes include Computer Science, Data Science, Software Engineering, Mathematics, or related degrees. A dedicated BSc Artificial Intelligence is available only where confirmed by a provider.", "Programming, linear algebra, probability, machine learning, software engineering, data governance, and communication.", "Software or data role to machine learning engineer to senior engineer, research engineer, or AI lead.", "Technology companies, research organisations, finance, health, agriculture, and public services.", "Study responsible AI and model evaluation; specialised roles may favour postgraduate training."),
        CareerSeed("Database Administrator", tech, "Keeps organisational databases reliable, secure, recoverable, and available to the people and systems that depend on them.", "Install and configure databases; manage accounts; monitor performance; plan backups; test recovery; troubleshoot and document changes.", "Mathematics, computer studies, and physics are useful preparation.", "Common routes include BSc Computer Science, Information Systems, Information Technology, or Software Engineering; confirm local course availability.", "SQL, data modelling, access control, backup and recovery, performance tuning, scripting, and attention to detail.", "IT support or database analyst to database administrator to database architect or data platform lead.", "Banks, government, telecommunications, health, universities, retailers, and software providers.", "Vendor database training may support a portfolio; certificate offerings and fees should be checked with providers."),
        CareerSeed("Web Developer", tech, "Builds and maintains websites and browser-based services, joining visual interfaces to reliable data and application behaviour.", "Create page layouts; implement interactions; connect APIs; test accessibility and performance; fix issues; maintain deployments.", "Mathematics, computer studies, design, and English can support this path.", "Common routes include BSc Computer Science, Software Engineering, IT, or design-related study plus a portfolio; there is no single required degree for every employer.", "HTML, CSS, JavaScript, responsive design, accessibility, APIs, testing, version control, and communication.", "Junior front-end or back-end developer to full-stack developer to senior developer or technical lead.", "Digital agencies, technology firms, media, government, education, and independent project work.", "A tested portfolio and current web standards are important; short-course certificates do not equal an accredited degree."),
        CareerSeed("IT Support Specialist", tech, "Helps people use computers, applications, accounts, and connected equipment safely and effectively.", "Respond to support requests; diagnose hardware and software issues; configure devices; manage accounts; record fixes; escalate complex incidents.", "Computer studies, mathematics, physics, and communication-focused subjects are useful.", "Routes include IT certificates, diplomas, or degrees such as BSc Information Technology or Computer Science, depending on employer and responsibilities.", "Troubleshooting, operating systems, networking, customer service, security awareness, documentation, and patience.", "Help-desk technician to desktop or systems support to administrator, network specialist, or service-desk lead.", "Most organisations with staff devices, including schools, hospitals, government, banks, and technology companies.", "Entry-level vendor training can help; check the issuing body's current certification requirements."),
        CareerSeed("Medical Doctor", health, "Assesses patients, diagnoses illness, recommends treatment, and works with other health professionals to promote and restore health.", "Take histories; examine patients; order and interpret investigations; treat or refer; maintain records; communicate risks and follow-up.", "Biology, chemistry, mathematics, physics, and English are commonly relevant; admission rules are institution- and country-specific.", "The professional award may be MBBS or MBChB, not a generic BSc. Study duration, prerequisite grades, clinical training, and registration must be verified with the medical school and regulator.", "Clinical reasoning, communication, compassion, ethics, teamwork, resilience, and accurate record keeping.", "Medical student to supervised internship/registration steps required locally, then medical officer and possible specialist training.", "Hospitals, clinics, public health, research, teaching, and humanitarian health services.", "Licensure and supervised practice are regulated; confirm requirements with the national medical council."),
        CareerSeed("Registered Nurse", health, "Provides and coordinates patient care, promotes health, supports families, and monitors people through illness and recovery.", "Assess and document patient needs; deliver nursing care; administer treatments within scope; educate patients; coordinate with clinical teams.", "Biology, chemistry, mathematics, and English are useful; exact admission subjects and grades vary.", "Qualifications may include a nursing diploma or Bachelor of Science in Nursing where offered. Duration, registration route, and entry conditions must be confirmed with the school and nursing council.", "Clinical observation, communication, compassion, teamwork, ethics, patient safety, and accurate documentation.", "Student nurse to registered nurse after required training and licensing to specialist, educator, manager, or advanced practice roles.", "Hospitals, health centres, community health, schools, NGOs, and public health programmes.", "Professional registration and scope-of-practice rules are country-specific; check the nursing regulator."),
        CareerSeed("Pharmacist", health, "Ensures medicines are selected, prepared, supplied, and used safely, and advises patients and health teams about treatment.", "Review prescriptions; check interactions; counsel patients; manage medicine supply; support medication safety; maintain required records.", "Chemistry, biology, mathematics, and English are useful; verify institution-specific prerequisites.", "The award is generally a Bachelor of Pharmacy or locally recognised professional pharmacy qualification, not automatically a BSc. Confirm duration, accreditation, and registration pathway.", "Pharmacology, attention to detail, ethics, communication, calculations, medicine safety, and teamwork.", "Pharmacy student to supervised practice/registration as required to pharmacist, specialist, manager, or pharmaceutical services roles.", "Community and hospital pharmacies, health services, regulators, research, and pharmaceutical organisations.", "Registration is regulated; verify current requirements with the pharmacy council and accredited school."),
        CareerSeed("Medical Laboratory Scientist", health, "Analyses patient samples and produces laboratory evidence that clinicians use to diagnose, monitor, and prevent disease.", "Receive and prepare specimens; perform validated tests; operate and maintain equipment; check quality; report results; follow biosafety rules.", "Biology, chemistry, mathematics, and physics are useful.", "Relevant awards may include a Bachelor of Medical Laboratory Sciences or BSc Medical Laboratory Science where named by the provider. Verify award, duration, accreditation, and prerequisites.", "Laboratory methods, quality assurance, biosafety, data accuracy, equipment handling, and teamwork.", "Laboratory trainee to registered scientist or technologist under local rules to section specialist, quality lead, or laboratory manager.", "Hospitals, diagnostic laboratories, public health, research, universities, and blood services.", "Check professional registration and scope requirements with the national regulator."),
        CareerSeed("Physiotherapist", health, "Assesses movement and function and helps people improve mobility, manage pain, and recover after injury or illness.", "Assess movement; agree rehabilitation goals; deliver exercise or manual interventions; measure progress; educate patients and caregivers.", "Biology, physics, mathematics, and English are useful.", "Possible professional awards include Bachelor of Physiotherapy or BSc Physiotherapy where offered. Confirm local title, duration, prerequisites, accreditation, and registration.", "Anatomy, movement science, assessment, communication, empathy, exercise planning, and clinical documentation.", "Student physiotherapist to supervised practice and registration where required to clinician, specialist, educator, or service lead.", "Hospitals, rehabilitation centres, sports services, community care, private clinics, and disability services.", "Professional registration and continuing education requirements vary by jurisdiction."),
        CareerSeed("Radiographer", health, "Produces diagnostic images or delivers therapeutic radiation as part of a clinical team, following safety and quality procedures.", "Prepare patients; operate imaging equipment; position safely; check image quality; maintain records; follow radiation-protection rules.", "Physics, biology, mathematics, and English are useful.", "Routes may include diagnostic radiography or medical imaging degrees; award titles, duration, clinical placement, and regulatory requirements depend on the institution and country.", "Anatomy, imaging technology, patient care, radiation safety, precision, communication, and teamwork.", "Radiography student to supervised/registered practitioner as locally required to modality specialist, educator, or department lead.", "Hospitals, imaging centres, cancer services, research, and equipment providers.", "Verify accreditation and registration requirements with the local radiography regulator."),
        CareerSeed("Graphic Designer", design, "Communicates ideas visually by creating layouts and visual assets for print, digital products, campaigns, and organisations.", "Discuss a brief; research audiences; develop concepts; create and revise layouts; prepare accessible, production-ready files.", "Art and design, computer studies, English, and business subjects may help; portfolio quality is important.", "Study routes may include BA Graphic Design, visual communication, or related design awards. Verify actual course titles and duration with the provider.", "Typography, layout, colour, visual research, design software, accessibility, creativity, and client communication.", "Junior designer to graphic designer to art director, brand designer, or independent studio owner.", "Agencies, publishers, media, government, education, NGOs, and freelance practice.", "Build a portfolio; software certificates are optional and not equivalent to a design degree."),
        CareerSeed("UI/UX Designer", design, "Researches users and designs digital interfaces that are understandable, accessible, and effective for real tasks.", "Interview users; map journeys; sketch interfaces; prototype flows; test usability; work with engineers; refine designs using evidence.", "Design, computer studies, mathematics, psychology, and English can all be relevant.", "Routes include interaction design, human-computer interaction, graphic design, information systems, or computer science. Degree titles and durations are institution-specific; a portfolio is valuable.", "User research, interaction design, accessibility, prototyping, visual hierarchy, usability testing, and collaboration.", "Junior product designer to UI/UX designer to senior product designer, UX researcher, or design lead.", "Technology companies, banks, consultancies, government digital services, and product teams.", "Build case studies that explain research, design decisions, and testing; no single certification is universally required."),
        CareerSeed("Interior Designer", design, "Plans interior spaces so they meet users' functional, aesthetic, accessibility, and safety needs.", "Gather client needs; measure spaces; create layouts and material concepts; coordinate drawings and suppliers; monitor project delivery.", "Art and design, mathematics, technical drawing, and physics can be useful.", "Routes include interior design, interior architecture, architecture, or spatial design qualifications. Professional title and registration rules vary by jurisdiction.", "Spatial planning, drawing, materials, building basics, accessibility, visualisation, budgeting, and client communication.", "Design assistant to interior designer to project lead, specialist consultant, or studio owner.", "Architecture and design practices, construction, hospitality, retail, property, and independent work.", "Portfolio and software skills support entry; confirm local building-code and professional requirements."),
        CareerSeed("Fashion Designer", design, "Develops clothing, accessories, or textile concepts and turns them into designs that can be sampled and produced.", "Research trends and users; sketch concepts; select fabrics; create specifications; review samples; coordinate production and presentation.", "Art and design, textiles, mathematics, and business subjects can be useful.", "Study routes may include fashion design, apparel, textiles, or costume design at BA, BSc, diploma, or other provider-defined level. Verify titles and duration.", "Drawing, textiles, pattern knowledge, visual research, communication, sustainability awareness, and project planning.", "Design assistant to fashion designer to collection lead, product developer, stylist, or label founder.", "Fashion houses, apparel manufacturers, textile firms, retail, media, costume, and entrepreneurship.", "A portfolio and practical sample work are useful; course completion is not professional accreditation."),
        CareerSeed("Industrial Designer", design, "Designs physical products by balancing user needs, form, materials, function, manufacture, and sustainability.", "Research use cases; sketch concepts; model prototypes; test usability; collaborate with engineers; refine designs for production.", "Art and design, mathematics, physics, computer studies, and technical drawing are useful.", "Routes include industrial/product design, product development, or design engineering awards. Check institution-specific BA/BSc titles and programme duration.", "Sketching, CAD, prototyping, materials, ergonomics, manufacturing awareness, research, and teamwork.", "Junior product designer to industrial designer to design lead, product strategist, or independent consultant.", "Manufacturing, consumer products, medical devices, furniture, transport, and design consultancies.", "Develop a portfolio of process and prototypes; software credentials vary by employer."),
        CareerSeed("Animation Designer", design, "Creates moving images and visual sequences for entertainment, education, advertising, games, and digital communication.", "Develop concepts and storyboards; create characters or assets; animate scenes; collaborate on sound and editing; revise work to briefs.", "Art and design, computer studies, English, and mathematics can help.", "Study routes include animation, film, illustration, game art, or digital media at BA/BSc or other levels. Confirm available awards and durations with each institution.", "Drawing, storytelling, timing, animation software, visual composition, patience, feedback, and collaboration.", "Junior animator to animator or technical artist to senior/lead animator, director, or studio owner.", "Animation studios, film and television, gaming, advertising, education, and digital media.", "A showreel is central to many applications; completion certificates are not accredited degrees."),
    )
    return rows.map { c ->
        val slug = c.title.lowercase().replace(Regex("[^a-z0-9]+"), "-").trim('-')
        val id = when (c.title) {
            "Software Developer" -> "career-data-engineer"
            "Cybersecurity Analyst" -> "career-cybersecurity"
            "Data Scientist" -> "career-data"
            else -> "career-guide-$slug"
        }
        OpportunityEntity(
            id = id, title = c.title, category = "Careers",
            subtitle = "${c.group} · Career pathway",
            overview = c.description,
            qualifications = c.qualifications,
            courses = "Main responsibilities: ${c.duties}\nRecommended school subjects: ${c.subjects}",
            skills = c.skills,
            pathways = "Career progression: ${c.progression}\nIndustries and organisations: ${c.sectors}\nFurther training: ${c.training}",
            provider = "Category: ${c.group}. General occupation reference: O*NET OnLine, https://www.onetonline.org/ (United States occupational information; local conditions can differ). Checked 2026-11-21. Programme, provider, duration, admission, licensing, and local school-subject requirements must be confirmed from official institutional and regulator sources.",
            requirements = c.subjects,
            duration = "No general duration assumed. Confirm the named qualification and duration with the chosen institution.",
            deadline = "Not applicable to a career profile."
        )
    }
}

