        FundingSeed("Mastercard Foundation Scholars Program", "Mastercard Foundation and partner institutions", "A partner-delivered scholarship programme supporting young people to access education and transition to dignified work.", "Countries and partner institutions listed in the Foundation's live directory; Malawi-specific intake depends on partner availability.", "Institution-specific selection; partner institutions define eligibility, levels, courses, documents, and deadlines.", "Foundation describes comprehensive support that can include tuition, accommodation, books/materials, mentoring, counselling, leadership development, and travel where applicable; partner terms control.", "Apply directly through a participating university or NGO; confirm that partner's course and current deadline.", "https://mastercardfdn.org/en/what-we-do/our-programs/mastercard-foundation-scholars-program/where-to-apply", "Dates are partner-specific; no single programme-wide deadline. Checked 2026-11-21."),
        FundingSeed("Chevening Scholarship", "UK Government, Foreign, Commonwealth and Development Office", "Funds eligible future leaders for a taught master's degree at a UK university.", "Applicants apply through their country page; Malawi page lists the national competition.", "Eligibility and course requirements are on the official country and programme pages; applicants need a valid application and eligible course choices.", "Scholarship benefits are set by Chevening award terms; review the official guidance for covered costs and conditions.", "Apply through the online Chevening system and follow the Malawi country-page instructions.", "https://www.chevening.org/scholarship/malawi/", "The Malawi page says 2027/2028 applications are closed. The next period has not been announced. Checked 2026-11-21."),
        FundingSeed("Commonwealth Scholarship", "Commonwealth Scholarship Commission in the UK", "Commonwealth Master's Scholarships support eligible candidates from qualifying low- and middle-income Commonwealth countries for full-time taught master's study in the UK.", "Eligible countries and approved UK programmes; check the CSC and Malawi nominating agency routes.", "Degree class, citizenship, development themes, and nomination conditions apply. Review the current CSC and nominator rules.", "Benefits and award duration are defined in the current official award terms; consult the CSC page.", "Apply through CSC Central and meet any separate national nominator process.", "https://cscuk.fcdo.gov.uk/scholarships/commonwealth-masters-scholarships/", "2027/2028 Master's applications closed; CSC deadline was 20 October 2026 at 16:00 BST. Next cycle unannounced. Checked 2026-11-21."),
        FundingSeed("Erasmus Mundus Scholarship", "European Union Erasmus+ and participating programme consortia", "Erasmus Mundus Joint Masters are international master's programmes delivered by university consortia; selected students may receive scholarships.", "Each master's consortium defines its countries, partner institutions, courses, and application route.", "Programme-specific academic, language, and document requirements apply; applicants apply to the consortium programme.", "EU information says scholarships may cover participation costs and contribute to travel, visa, and living expenses; exact award depends on programme/call.", "Search the official Erasmus Mundus catalogue, choose a programme, then apply directly to its consortium.", "https://erasmus-plus.ec.europa.eu/opportunities/opportunities-for-individuals/students/erasmus-mundus-joint-masters", "Most programmes set their own dates; no single scholarship deadline. Checked 2026-11-21."),
        FundingSeed("Fulbright Scholarship", "U.S. Department of State and country programme offices", "Fulbright exchange awards support study, teaching, or research, with programme type and eligible applicants varying by country.", "Country-specific programmes and host-country arrangements; the Malawi office publishes relevant opportunities.", "Eligibility, degree level, fields, and whether the applicant is eligible as a Malawian vary by specific award. Check the Malawi country and embassy guidance.", "Award support varies by programme; confirm grant terms on the active country call.", "Use the official Fulbright application route and contact the U.S. Embassy/eligible country office for the relevant award.", "https://mw.usembassy.gov/education-culture/fulbright/", "No current Malawi outbound student application cycle confirmed from this source; check official country notices. Checked 2026-11-21.")
    )
    return rows.map { s ->
        OpportunityEntity(
            id = "scholarship-guide-" + s.title.lowercase().replace(Regex("[^a-z0-9]+"), "-").trim('-'),
            title = s.title, category = "Scholarships", subtitle = s.providerName,
            overview = s.description, provider = "Provider: ${s.providerName}\nOfficial source: ${s.url}\nLast checked: 2026-11-21",
            qualifications = "Study levels, eligible subjects, nationality/residency, age requirements, and academic criteria: check the current official call. No age condition or qualification threshold is inferred.",
            courses = "Countries/institutions: ${s.coverage}\nSupporting documents: follow the current official call; commonly requested document lists are not assumed here.",
            skills = "Not applicable as a training course.",
            pathways = "Application procedure: ${s.procedure}\nFinancial benefits: ${s.benefit}",
            requirements = s.eligibility,
            duration = "Funding duration is set by each award or call; check official terms.",
            deadline = s.status,
            applicationUrl = s.url
        )
    }
}

private data class InternshipSeed(val title: String, val industry: String, val description: String, val fields: String, val skills: String, val url: String)

private fun internships(): List<OpportunityEntity> {
