        InternshipSeed("ICT Internship", "Technology companies", "Employer-dependent internship category for supervised experience in information and communications technology; this is not a confirmed vacancy.", "Students or graduates in IT, computer science, networking, software, or a related field when required by the employer.", "Basic troubleshooting, computing, communication, documentation, and the technical skills named in a current advert.", ""),
        InternshipSeed("Accounting Internship", "Accounting firms", "Employer-dependent internship category offering workplace exposure in accounting or finance; no specific vacancy is represented.", "Accounting, finance, business, or related students/graduates where the employer requires them.", "Numeracy, spreadsheet use, accuracy, confidentiality, communication, and accounting knowledge appropriate to the placement.", ""),
