        TrainingSeed("Networking Basics", "Cisco Networking Academy", "Beginner learning about how computer networks operate and the technologies that connect devices.", "Network devices, connectivity, addressing, and networking concepts as listed in the course.", "https://www.netacad.com/", "Check current course page; duration not captured in this record.", "Check current course page for any badge or completion recognition conditions."),
        TrainingSeed("Google Digital Skills", "Google", "Google learning resources for digital skills; the exact curriculum and enrolment route depend on the selected course.", "Digital productivity, online marketing, analytics, or other topics shown in Google's current learning catalogue.", "https://grow.google/intl/ssa/", "Course-specific; check the selected course page.", "Certificate availability and any assessment or fee conditions vary by course; verify before enrolling."),
