        TrainingSeed("Elements of AI", "University of Helsinki and MinnaLearn", "An online introductory course intended to explain core AI concepts to a broad audience.", "AI concepts, machine learning, neural networks, and societal implications as shown in the course.", "https://course.elementsofai.com/", "Self-paced; check the course site for current expected workload.", "Check the current course page for certificate conditions; completion recognition is not an accredited degree."),
        TrainingSeed("Google Analytics Training", "Google", "Google's Analytics learning resources help learners understand the current Google Analytics platform and measurement concepts.", "Analytics setup, reporting, measurement, and analysis using the current learning materials.", "https://support.google.com/analytics/answer/15440208?hl=en", "Self-paced resources; course availability and duration may change.", "Google lists training courses and a certification; check current course and assessment conditions. This is not an academic qualification.")
    )
