        OpportunityEntity(
            id = "training-guide-" + t.title.lowercase().replace(Regex("[^a-z0-9]+"), "-").trim('-'),
            title = t.title, category = "Training", subtitle = "${t.providerName} · Online resources",
            overview = t.description,
            qualifications = "Intended learners: check the provider's course page. Entry and prior-knowledge requirements are course-specific; no prerequisite is assumed unless published.",
            courses = "Topics covered: ${t.topics}\nSkills gained: introductory knowledge in the topics listed by the provider; outcomes depend on modules completed.",
            skills = t.topics,
